function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // center of the flower
  let centerX = W / 2;
  let centerY = H / 2;
  // draw stem
  ctx.beginPath();
  ctx.moveTo(centerX, H - 20);
  ctx.lineTo(centerX, H / 2 + 50 * Math.sin(t));
  ctx.stroke();
  // draw flower
  let radius = 20 + 10 * Math.sin(t * 2);
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, 2 * Math.PI);
  ctx.stroke();
  // draw petals
  for (let i = 0; i < 6; i++) {
    let angle = i * Math.PI / 3 + t;
    let petalX = centerX + (radius + 10 * Math.sin(t)) * Math.cos(angle);
    let petalY = centerY + (radius + 10 * Math.sin(t)) * Math.sin(angle);
    ctx.beginPath();
    ctx.arc(petalX, petalY, 10, 0, 2 * Math.PI);
    ctx.stroke();
  }
  ctx.restore();
}
